mapper.select:
select r.link_rule_code from b_short_link_transfer_rule r
r.status = 1
and r.create_time >= #{queryStartTime}
and r.create_time < #{queryEndTime}
and r.link_rule_name like CONCAT('%',#{linkRuleName},'%')
group by r.link_rule_code order by r.create_time desc

SELECT IFNULL(COUNT(*), 0) FROM ( SELECT 1 FROM b_short_link_visit_log a
and a.link_rule_code = #{linkRuleCode}
GROUP BY a.short_url, a.target_key_md5, a.ip, a.status ) tmp

mapper.insert:
insert into b_short_link_transfer_rule (id, link_rule_code, link_rule_name, 
  api_code, status, create_time, 
  update_time, create_by, update_by
  )
values (#{id,jdbcType=BIGINT}, #{linkRuleCode,jdbcType=VARCHAR}, #{linkRuleName,jdbcType=VARCHAR}, 
  #{apiCode,jdbcType=VARCHAR}, #{status,jdbcType=TINYINT}, #{createTime,jdbcType=TIMESTAMP}, 
  #{updateTime,jdbcType=TIMESTAMP}, #{createBy,jdbcType=VARCHAR}, #{updateBy,jdbcType=VARCHAR}
  )
